// How the fake site behaves: speeds, timings, energy, blast statistics. Each value says where it
// came from: the spec (PROTOCOL.md), measured on the live gateway (research/README.md and the
// fixtures), or guessed (no evidence either way; to be re-checked against the live site).
//
// These are deliberately separate from the product's src/params.ts. The fake is the oracle the
// product is tested against; if it borrowed the product's beliefs, a wrong belief would make the
// oracle agree with it. Site geometry is not here: it comes from the site config (fake/dlh1.ts).

export interface Behaviour {
  // Simulation
  tickMs: number;                 // decided: physics step; deadman and blast times resolve to it
  telemetryPeriodMs: number;      // spec §4.2 "about 5 Hz"; t_device_ms steps of 200-202 ms measured
  heartbeatPeriodMs: number;      // spec §4.3, 2 s; 2.006-2.014 s measured

  // Speeds (m/s)
  autoSpeedEmpty: number;         // spec §3
  autoSpeedLoaded: number;        // spec §3
  reverseSpeedEmpty: number;      // measured: probe S3, EXIT_ZONE reversed at 3.0 m/s
  reverseSpeedLoaded: number;     // spec-assumed (2.0, the autonomous loaded speed); not measured. L0.P runs 1.5 too
  manualSpeedEmpty: number;       // spec §3, at full throttle
  manualSpeedLoaded: number;      // spec §3, at full throttle
  limpSpeed: number;              // spec §6.6, 1.0 m/s; guessed: scaled by |throttle| like the others

  // Work cycle
  loadMs: number;                 // spec §3 "about 20 s"
  dumpMs: number;                 // spec §3 "about 12 s"
  workStopBeforeEndM: number;     // measured: trucks load and dump at offset 59.95 of a 60 m segment
  payloadKg: number;              // measured: 42000.0 in every loaded message
  chargeBelowPct: number;         // spec §3
  chargeToPct: number;            // spec §3
  chargeRatePctPerS: number;      // guessed: no CHARGING seen live; Sam's "a ten-minute charge" (~60 % in 600 s)

  // Energy (% of charge per km travelled; nothing while stopped)
  drainEmptyPctPerKm: number;     // measured: fleet 5.99 %/km empty (weak-pack, reverse-exit-zone fixtures)
  drainLoadedPctPerKm: number;    // measured: fleet 9.00 %/km loaded (weak-pack fixture)

  // Commands and control
  commandDelayMinMs: number;      // spec §5 "1 to 6 seconds"; live: HOLD 3.2 s, EXIT_ZONE ~4 s, RESUME 1.3 s
  commandDelayMaxMs: number;
  queueing: 'spec';               // L0.P: 'spec' only in milestone 1; the pessimistic version is milestone 2
  deadmanMs: number;              // spec §6.3; deadman seen 0.4-0.6 s after the grant live
  leaseIdleTimeoutMs: number;     // spec §6.4; 10.1 s measured
  exitStopOutsideM: number;       // spec §5 "about 2 m"; 2.0 m measured (probe S3)
  driveRejectIntervalMs: number;  // spec §4.7, at most one per vehicle per reason per second
  limpHomeFaults: string[];       // spec §6.6: HYD_PRESSURE_LOW allows limp-home; others guessed not to
  depletedFault: string;          // spec §6.6 / measured: weak-pack fixture

  // Transport
  authTimeoutMs: number;          // spec §1.1
  maxConnections: number;         // spec §1.1
  maxLineBytes: number;           // spec §1, 64 KiB
  maxBehindBytes: number;         // spec §1, "about 4 MB"

  // Blasts (random schedule)
  firstBlastMinMs: number;        // guessed: the captures start mid-day
  firstBlastMaxMs: number;
  blastSpacingMinMs: number;      // measured: 276-318 s between CLOSINGs
  blastSpacingMaxMs: number;
  closedMinMs: number;            // measured: closed for 66-111 s
  closedMaxMs: number;
  cancelProbability: number;      // measured: 2 cancelled of 7 blasts across the three captures
  secondZoneProbability: number;  // guessed: two zones closing at once seen once (probe session)
  secondZoneOffsetMs: number;     // measured once: two zones CLOSING 30 s apart (fixture two-zones-closing)
  blastBay: boolean;              // open question 5: can BAY be closed? false until answered (L0.F adds it)
}

export const DEFAULT_BEHAVIOUR: Readonly<Behaviour> = Object.freeze({
  tickMs: 50,
  telemetryPeriodMs: 200,
  heartbeatPeriodMs: 2_000,

  autoSpeedEmpty: 3.0,
  autoSpeedLoaded: 2.0,
  reverseSpeedEmpty: 3.0,
  reverseSpeedLoaded: 2.0,
  manualSpeedEmpty: 4.0,
  manualSpeedLoaded: 3.0,
  limpSpeed: 1.0,

  loadMs: 20_000,
  dumpMs: 12_000,
  workStopBeforeEndM: 0.05,
  payloadKg: 42_000,
  chargeBelowPct: 25,
  chargeToPct: 90,
  chargeRatePctPerS: 0.1,

  drainEmptyPctPerKm: 6.0,
  drainLoadedPctPerKm: 9.0,

  commandDelayMinMs: 1_000,
  commandDelayMaxMs: 6_000,
  queueing: 'spec',
  deadmanMs: 500,
  leaseIdleTimeoutMs: 10_000,
  exitStopOutsideM: 2.0,
  driveRejectIntervalMs: 1_000,
  limpHomeFaults: ['HYD_PRESSURE_LOW'],
  depletedFault: 'BATTERY_DEPLETED',

  authTimeoutMs: 10_000,
  maxConnections: 16,
  maxLineBytes: 64 * 1024,
  maxBehindBytes: 4 * 1024 * 1024,

  firstBlastMinMs: 60_000,
  firstBlastMaxMs: 240_000,
  blastSpacingMinMs: 276_000,
  blastSpacingMaxMs: 318_000,
  closedMinMs: 66_000,
  closedMaxMs: 111_000,
  cancelProbability: 2 / 7,
  secondZoneProbability: 0.2,
  secondZoneOffsetMs: 30_000,
  blastBay: false,
});
// The fake's default site: DLH-1 exactly as its hello describes it in research/fixtures (route,
// vehicles, loop length), plus the notice length every captured closure had (120 s). This is the
// only file in fake/ allowed this site's names and numbers (test/source-rules.test.ts).
import type { SiteConfig } from './model.ts';

export const DLH1: SiteConfig = {
  site_id: 'DLH-1',
  vehicles: ['HT-01', 'HT-02', 'HT-03', 'HT-04', 'HT-05', 'HT-06', 'HT-07', 'HT-08', 'HT-09', 'HT-10', 'HT-11', 'HT-12'],
  route: [
    { segment_id: 'SEG-BAY', zone_id: 'BAY', length_m: 80.0, kind: 'bay', start_m: 0.0 },
    { segment_id: 'SEG-DEC-1', zone_id: 'DECLINE', length_m: 250.0, kind: 'transit', start_m: 80.0 },
    { segment_id: 'SEG-DEC-2', zone_id: 'DECLINE', length_m: 250.0, kind: 'transit', start_m: 330.0 },
    { segment_id: 'SEG-L4N-1', zone_id: 'L4_NORTH', length_m: 200.0, kind: 'transit', start_m: 580.0 },
    { segment_id: 'SEG-DRAW-12', zone_id: 'DRAW_12', length_m: 60.0, kind: 'load', start_m: 780.0 },
    { segment_id: 'SEG-L4S-1', zone_id: 'L4_SOUTH', length_m: 200.0, kind: 'transit', start_m: 840.0 },
    { segment_id: 'SEG-INC-1', zone_id: 'INCLINE', length_m: 250.0, kind: 'transit', start_m: 1040.0 },
    { segment_id: 'SEG-INC-2', zone_id: 'INCLINE', length_m: 250.0, kind: 'transit', start_m: 1290.0 },
    { segment_id: 'SEG-TIP-1', zone_id: 'TIP', length_m: 60.0, kind: 'dump', start_m: 1540.0 },
  ],
  loop_length_m: 1600.0,
  noticeMs: 120_000,
};
// The fake gateway: connections, the auth flow (PROTOCOL.md §1.1), line parsing, command_id
// de-duplication (§5), and broadcast of everything to every client. The site itself is the model
// (fake/model.ts). Transports plug in through `attach`: the in-process TestClient below for tests,
// and fake/tls.ts for research/probe.py.
//
// Layers, so milestone 2 adds rather than rewrites: model (truth) -> telemetry built from it ->
// gateway (this file) -> Radio (one per client) -> transport. Radio faults (loss, duplicates,
// reordering, truncation, lost acks, link outages) replace PERFECT_RADIO; telemetry faults sit in
// the model's telemetry step; ACCEPTED-then-ignored sits where the model applies an effect.
import type { Clock, TimerHandle } from '../src/clock.ts';
import { ACTIONS, type Action, type AuthErrorReason, type CommandAck, type GatewayMessage } from '../src/protocol.ts';
import { DEFAULT_BEHAVIOUR, type Behaviour } from './behaviour.ts';
import { SiteModel, type AckResult, type Blasts, type SiteConfig, type TruckInit, type TruckTruth } from './model.ts';
import type { ZoneState } from '../src/protocol.ts';

export interface FakeConfig {
  seed: number;
  site: SiteConfig;
  blasts?: Blasts;            // default 'random'
  trucks?: TruckInit[];       // placement for some or all trucks; the rest are spread by the seed
  behaviour?: Partial<Behaviour>;
}

export interface Sink {
  write(line: string): void; // one NDJSON line, without the newline
  close(): void;
}

// Delivery of one line to one client. Milestone 1 delivers everything, at once, in order.
export interface Radio {
  deliver(conn: Connection, line: string): void;
}
export const PERFECT_RADIO: Radio = { deliver: (conn, line) => conn.write(line) };

const EMAIL = /^[^@\s]+@[^@\s]+\.[^@\s]+$/;
const MAX_COMMAND_ID = 128;

export class Connection {
  authed = false;
  closed = false;
  email: string | null = null;
  authTimer: TimerHandle | null = null;
  readonly #gw: FakeGateway;
  readonly #sink: Sink;

  constructor(gw: FakeGateway, sink: Sink) {
    this.#gw = gw;
    this.#sink = sink;
  }

  // A line from the client, without its newline.
  receive(line: string): void {
    if (this.closed) return;
    this.#gw.receive(this, line);
  }

  // The transport says the peer has gone.
  disconnect(): void {
    this.#gw.drop(this, false);
  }

  write(line: string): void {
    if (!this.closed) this.#sink.write(line);
  }

  closeSink(): void {
    this.#sink.close();
  }
}

export class FakeGateway {
  readonly model: SiteModel;
  readonly behaviour: Readonly<Behaviour>;
  readonly #clock: Clock;
  readonly #conns: Connection[] = [];
  readonly #seen = new Map<string, { key: string; ack: CommandAck }>();
  #radio: Radio = PERFECT_RADIO;

  constructor(clock: Clock, config: FakeConfig) {
    const b: Behaviour = { ...DEFAULT_BEHAVIOUR, ...config.behaviour };
    if (b.queueing !== 'spec') {
      throw new Error(`queueing '${String(b.queueing)}' is not modelled yet: only the spec version exists (TESTING.md L0.P, milestone 2)`);
    }
    this.behaviour = Object.freeze(b);
    this.#clock = clock;
    this.model = new SiteModel(clock, (m) => this.#broadcast(m), {
      seed: config.seed, site: config.site, behaviour: b, blasts: config.blasts ?? 'random', trucks: config.trucks ?? [],
    });
  }

  start(): void { this.model.start(); }
  stop(): void { this.model.stop(); }

  // For milestone 2's radio faults.
  setRadio(radio: Radio): void { this.#radio = radio; }

  // Truth and fault access for tests.
  truth(id: string): TruckTruth { return this.model.truth(id); }
  truthAll(): TruckTruth[] { return this.model.truthAll(); }
  zone(id: string): ZoneState { return this.model.zone(id); }
  injectFault(id: string, code: string): void { this.model.injectFault(id, code); }

  // A new connection from a transport. It must authenticate within the timeout.
  attach(sink: Sink): Connection {
    const conn = new Connection(this, sink);
    this.#conns.push(conn);
    conn.authTimer = this.#clock.setTimeout(() => {
      if (!conn.authed && !conn.closed) this.#authError(conn, 'AUTH_TIMEOUT');
    }, this.behaviour.authTimeoutMs);
    return conn;
  }

  // An in-process client, for tests.
  connect(): TestClient {
    return new TestClient(this);
  }

  receive(conn: Connection, line: string): void {
    if (Buffer.byteLength(line, 'utf8') > this.behaviour.maxLineBytes) { this.drop(conn, true); return; } // §7
    if (!conn.authed) { this.#auth(conn, line); return; }
    let m: unknown;
    try { m = JSON.parse(line); } catch { m = undefined; }
    if (!isObject(m)) { this.#broadcast(this.#ack('<unparseable>', null, { status: 'REJECTED', reason: 'BAD_JSON' })); return; }
    if (m.type === 'command') this.#command(m);
    else if (m.type === 'drive') this.model.drive(m);
    // §7: anything else is ignored
  }

  drop(conn: Connection, closeSink: boolean): void {
    if (conn.closed) return;
    conn.closed = true;
    if (conn.authTimer) this.#clock.clearTimeout(conn.authTimer);
    const i = this.#conns.indexOf(conn);
    if (i >= 0) this.#conns.splice(i, 1);
    if (closeSink) conn.closeSink();
  }

  #auth(conn: Connection, line: string): void {
    if (conn.authTimer) this.#clock.clearTimeout(conn.authTimer);
    let m: unknown;
    try { m = JSON.parse(line); } catch { this.#authError(conn, 'BAD_AUTH'); return; }
    if (!isObject(m) || m.type !== 'auth') { this.#authError(conn, 'AUTH_REQUIRED'); return; }
    if (typeof m.email !== 'string' || !EMAIL.test(m.email)) { this.#authError(conn, 'BAD_EMAIL'); return; }
    if (this.#conns.filter((c) => c.authed).length >= this.behaviour.maxConnections) { this.#authError(conn, 'TOO_MANY_CONNECTIONS'); return; }
    conn.authed = true;
    conn.email = m.email;
    conn.write(JSON.stringify(this.model.hello(m.email)));
  }

  #authError(conn: Connection, reason: AuthErrorReason): void {
    conn.write(JSON.stringify({ type: 'auth_error', reason }));
    this.drop(conn, true);
  }

  #command(m: Record<string, unknown>): void {
    const vehicle = typeof m.vehicle_id === 'string' ? m.vehicle_id : null;
    const id = m.command_id;
    if (typeof id !== 'string' || id.length === 0 || id.length > MAX_COMMAND_ID) {
      const echo = typeof id === 'string' && id.length > 0 ? id : '<missing>';
      this.#broadcast(this.#ack(echo, vehicle, { status: 'REJECTED', reason: 'BAD_COMMAND_ID' }));
      return;
    }
    const key = canonical(m);
    const prev = this.#seen.get(id);
    if (prev) {
      // §5: same payload returns the original result and does not execute again
      if (prev.key === key) this.#broadcast({ ...prev.ack, server_time_ms: this.#clock.now() });
      else this.#broadcast(this.#ack(id, vehicle, { status: 'REJECTED', reason: 'COMMAND_ID_REUSED' }));
      return;
    }
    let result: AckResult;
    if (typeof m.operator_id !== 'string' || m.operator_id.length === 0) result = { status: 'REJECTED', reason: 'MISSING_OPERATOR' };
    else if (vehicle === null || !this.model.hasVehicle(vehicle)) result = { status: 'REJECTED', reason: 'UNKNOWN_VEHICLE' };
    else if (!(ACTIONS as readonly unknown[]).includes(m.action)) result = { status: 'REJECTED', reason: 'UNSUPPORTED_ACTION' };
    else {
      result = this.model.command({
        command_id: id, vehicle_id: vehicle, action: m.action as Action, operator_id: m.operator_id, force: m.force, lease_id: m.lease_id,
      });
    }
    const ack = this.#ack(id, vehicle, result);
    this.#seen.set(id, { key, ack });
    this.#broadcast(ack);
  }

  #ack(commandId: string, vehicle: string | null, r: AckResult): CommandAck {
    return {
      type: 'command_ack', command_id: commandId, vehicle_id: vehicle, status: r.status, server_time_ms: this.#clock.now(),
      ...(r.reason !== undefined ? { reason: r.reason } : {}),
      ...(r.holder !== undefined ? { holder: r.holder } : {}),
      ...(r.lease_id !== undefined ? { lease_id: r.lease_id } : {}),
      ...(r.lease_idle_timeout_ms !== undefined ? { lease_idle_timeout_ms: r.lease_idle_timeout_ms } : {}),
      ...(r.deadman_ms !== undefined ? { deadman_ms: r.deadman_ms } : {}),
    };
  }

  #broadcast(m: GatewayMessage): void {
    const line = JSON.stringify(m);
    for (const c of [...this.#conns]) if (c.authed && !c.closed) this.#radio.deliver(c, line);
  }
}

// An in-process client: what a transport would deliver, as lines and parsed messages.
export class TestClient {
  readonly lines: string[] = [];
  closed = false;
  readonly #parsed: GatewayMessage[] = [];
  readonly #listeners: Array<(m: GatewayMessage) => void> = [];
  readonly #conn: Connection;

  constructor(gw: FakeGateway) {
    this.#conn = gw.attach({
      write: (line) => {
        this.lines.push(line);
        let m: GatewayMessage;
        try { m = JSON.parse(line) as GatewayMessage; } catch { return; } // milestone 2 truncates lines
        this.#parsed.push(m);
        for (const fn of this.#listeners) fn(m);
      },
      close: () => { this.closed = true; },
    });
  }

  send(msg: object | string): void {
    this.#conn.receive(typeof msg === 'string' ? msg : JSON.stringify(msg));
  }

  messages(): GatewayMessage[] {
    return this.#parsed;
  }

  onMessage(fn: (m: GatewayMessage) => void): void {
    this.#listeners.push(fn);
  }

  close(): void {
    this.#conn.disconnect();
    this.closed = true;
  }
}

function isObject(x: unknown): x is Record<string, unknown> {
  return typeof x === 'object' && x !== null && !Array.isArray(x);
}

// Key order does not make a different payload.
function canonical(x: unknown): string {
  if (Array.isArray(x)) return `[${x.map(canonical).join(',')}]`;
  if (isObject(x)) return `{${Object.keys(x).sort().map((k) => `${JSON.stringify(k)}:${canonical(x[k])}`).join(',')}}`;
  return JSON.stringify(x);
}
// Run the fake gateway over TLS on the real clock, for research/probe.py and by-hand checks.
//
//   openssl req -x509 -newkey rsa:2048 -nodes -days 1 -subj /CN=127.0.0.1 \
//     -addext subjectAltName=IP:127.0.0.1 -keyout key.pem -out cert.pem
//   node fake/main.ts --key key.pem --cert cert.pem [--port 7443] [--seed 1] [--blasts random|none]
//                     [--fault <vehicle>:<code> ...]
//
// Then point a client at it with GATEWAY_HOST=127.0.0.1, GATEWAY_PORT and SSL_CERT_FILE=cert.pem.
// The default site is DLH-1 (fake/dlh1.ts). Never point a probe at the real gateway by accident:
// this prints the address it serves.
import { readFileSync } from 'node:fs';
import { parseArgs } from 'node:util';
import { SystemClock } from '../src/clock.ts';
import { FakeGateway } from './gateway.ts';
import { DLH1 } from './dlh1.ts';
import { listenTls } from './tls.ts';

const { values } = parseArgs({
  options: {
    key: { type: 'string' },
    cert: { type: 'string' },
    host: { type: 'string', default: '127.0.0.1' },
    port: { type: 'string', default: '0' },
    seed: { type: 'string', default: '1' },
    blasts: { type: 'string', default: 'random' },
    fault: { type: 'string', multiple: true, default: [] },
  },
});
if (!values.key || !values.cert) {
  console.error('usage: node fake/main.ts --key key.pem --cert cert.pem [--port N] [--seed N] [--blasts random|none] [--fault VEHICLE:CODE]');
  process.exit(2);
}
if (values.blasts !== 'random' && values.blasts !== 'none') {
  console.error(`--blasts must be random or none, not ${values.blasts}`);
  process.exit(2);
}

const gw = new FakeGateway(new SystemClock(), { seed: Number(values.seed), site: DLH1, blasts: values.blasts });
for (const f of values.fault) {
  const [vehicle, code] = f.split(':');
  if (!vehicle || !code) { console.error(`--fault wants VEHICLE:CODE, not ${f}`); process.exit(2); }
  gw.injectFault(vehicle, code);
}
gw.start();
const server = await listenTls(gw, { key: readFileSync(values.key), cert: readFileSync(values.cert), host: values.host, port: Number(values.port) });
console.log(`fake gateway (site ${DLH1.site_id}, seed ${values.seed}) listening on ${values.host}:${server.port}`);

const shutdown = () => { gw.stop(); void server.close().then(() => process.exit(0)); };
process.on('SIGINT', shutdown);
process.on('SIGTERM', shutdown);
// Seeded random numbers for the fake (L0.C4). sfc32, seeded through splitmix32. Each concern gets
// its own stream (`fork`), so a test's commands never shift the blast schedule or the initial
// placement, and milestone 2's fault injectors can add streams without disturbing these.

function splitmix32(seed: number): () => number {
  let s = seed >>> 0;
  return () => {
    s = (s + 0x9e3779b9) >>> 0;
    let z = s;
    z = Math.imul(z ^ (z >>> 16), 0x85ebca6b) >>> 0;
    z = Math.imul(z ^ (z >>> 13), 0xc2b2ae35) >>> 0;
    return (z ^ (z >>> 16)) >>> 0;
  };
}

export class Rng {
  #a: number; #b: number; #c: number; #d: number;

  constructor(seed: number) {
    const sm = splitmix32(seed);
    this.#a = sm(); this.#b = sm(); this.#c = sm(); this.#d = sm();
    for (let i = 0; i < 12; i++) this.#nextU32();
  }

  // A child stream named by `label`: same seed and label, same stream.
  fork(label: string): Rng {
    let h = 0x811c9dc5;
    for (let i = 0; i < label.length; i++) h = Math.imul(h ^ label.charCodeAt(i), 0x01000193) >>> 0;
    return new Rng((this.#nextU32() ^ h) >>> 0);
  }

  // Uniform in [0, 1).
  next(): number {
    return this.#nextU32() / 4294967296;
  }

  #nextU32(): number {
    const t = (((this.#a + this.#b) >>> 0) + this.#d) >>> 0;
    this.#d = (this.#d + 1) >>> 0;
    this.#a = this.#b ^ (this.#b >>> 9);
    this.#b = (this.#c + (this.#c << 3)) >>> 0;
    this.#c = ((this.#c << 21) | (this.#c >>> 11)) >>> 0;
    this.#c = (this.#c + t) >>> 0;
    return t;
  }

  uniform(min: number, max: number): number {
    return min + (max - min) * this.next();
  }

  int(min: number, maxInclusive: number): number {
    return min + Math.floor(this.next() * (maxInclusive - min + 1));
  }

  chance(p: number): boolean {
    return this.next() < p;
  }

  pick<T>(items: readonly T[]): T {
    if (items.length === 0) throw new RangeError('pick from an empty list');
    return items[Math.floor(this.next() * items.length)]!;
  }

  hex(digits: number): string {
    let s = '';
    for (let i = 0; i < digits; i++) s += Math.floor(this.next() * 16).toString(16);
    return s;
  }
}
// TCP + TLS NDJSON transport for the fake gateway (PROTOCOL.md §1), so real clients such as
// research/probe.py can talk to it. One line per message; lines over 64 KiB close the connection;
// a client more than about 4 MB behind on reading is dropped. The certificate is generated by
// whoever starts it (tests do it at test time); none is committed.
import { createServer, type TLSSocket } from 'node:tls';
import { StringDecoder } from 'node:string_decoder';
import type { FakeGateway } from './gateway.ts';

export interface TlsOptions {
  key: string | Buffer;
  cert: string | Buffer;
  host?: string; // default 127.0.0.1: the fake is not for the open network
  port?: number; // default 0: any free port
}

export interface TlsServer {
  readonly port: number;
  close(): Promise<void>;
}

export async function listenTls(gw: FakeGateway, opts: TlsOptions): Promise<TlsServer> {
  const sockets = new Set<TLSSocket>();
  const { maxLineBytes, maxBehindBytes } = gw.behaviour;

  const server = createServer({ key: opts.key, cert: opts.cert }, (socket) => {
    sockets.add(socket);
    const decoder = new StringDecoder('utf8');
    let buf = '';
    let open = true;
    const conn = gw.attach({
      write(line) {
        if (!open) return;
        if (socket.writableLength > maxBehindBytes) { open = false; socket.destroy(); return; } // §1: slow reader
        socket.write(line + '\n');
      },
      close() {
        if (!open) return;
        open = false;
        socket.end();
      },
    });
    socket.on('data', (chunk: Buffer) => {
      buf += decoder.write(chunk);
      for (let i = buf.indexOf('\n'); i >= 0 && open; i = buf.indexOf('\n')) {
        const line = buf.slice(0, i);
        buf = buf.slice(i + 1);
        conn.receive(line.endsWith('\r') ? line.slice(0, -1) : line);
      }
      if (open && Buffer.byteLength(buf, 'utf8') > maxLineBytes) conn.receive(buf); // over-long: the gateway closes
    });
    socket.on('close', () => {
      open = false;
      sockets.delete(socket);
      conn.disconnect();
    });
    socket.on('error', () => { /* 'close' follows and tidies up */ });
  });

  await new Promise<void>((resolve, reject) => {
    server.once('error', reject);
    server.listen(opts.port ?? 0, opts.host ?? '127.0.0.1', () => resolve());
  });
  const addr = server.address();
  const port = typeof addr === 'object' && addr ? addr.port : 0;

  return {
    port,
    close: () => new Promise<void>((resolve) => {
      for (const s of sockets) s.destroy();
      server.close(() => resolve());
    }),
  };
}

1	// The fake site's truth (TESTING.md L0.M): trucks on the loop, the duty cycle, supervisory
2	// commands with their delay and queuing, leases and the deadman, e-stops, faults and blasts.
3	//
4	// It knows no site. Geometry comes from SiteConfig through src/site.ts, and the places where trucks
5	// load, dump and charge come from segment kinds ('load', 'dump', 'bay'), as PROTOCOL.md §3 names
6	// them. It never reads the wall clock: one tick timer on the injected Clock drives everything, so
7	// a ManualClock runs a day in milliseconds and the same seed and inputs replay byte for byte.
8	//
9	// What is sent is built from this truth. Milestone 2's fault injectors sit between the two
10	// (telemetry faults) and between the gateway and each client (radio faults); the truth stays here.
11	import type { Clock, TimerHandle } from '../src/clock.ts';
12	import type {
13	  Action, CommandAck, GatewayMessage, Hello, LeaseEvent, RejectReason, RouteSegment, Task, Telemetry,
14	  VehicleState, ZoneState,
15	} from '../src/protocol.ts';
16	import { buildSite, type Segment, type Site, type Zone } from '../src/site.ts';
17	import type { Behaviour } from './behaviour.ts';
18	import { Rng } from './rng.ts';
19	
20	export interface SiteConfig {
21	  site_id: string;
22	  vehicles: string[];
23	  route: RouteSegment[];
24	  loop_length_m: number;
25	  noticeMs: number; // CLOSING to effective_at for every blast at this site
26	}
