# Per-run report over a capture.jsonl, so runs can be compared like for like.
import json, sys, collections, statistics as st

rows = [json.loads(l) for l in open(sys.argv[1])]
T0 = rows[0]['rx_ms']
def t(rx): return '%+6.0fs' % ((rx - T0) / 1000)
def num(x):
    if isinstance(x, bool): return None
    if isinstance(x, (int, float)): return float(x)
    return None

route = None; start = {}; length = {}
for r in rows:
    if r['kind'] == 'msg' and r['m']['type'] == 'hello':
        route = r['m']['route']; start = {s['segment_id']: s['start_m'] for s in route}; length = {s['segment_id']: s['length_m'] for s in route}
        break
def pos(m):
    try: return start[m['segment_id']] + float(m['offset_m'])
    except Exception: return None

# ---- link ----
print('== LINK ==')
dur = (rows[-1]['rx_ms'] - T0) / 1000
kinds = collections.Counter(r['kind'] if r['kind'] != 'msg' else r['m']['type'] for r in rows)
print('duration %.0fs  counts %s' % (dur, dict(kinds)))
for r in rows:
    if r['kind'] in ('connected', 'closed_by_peer', 'error', 'rx_timeout'): print(' ', t(r['rx_ms']), r['kind'], r.get('err', ''), r.get('attempt', ''))
    if r['kind'] == 'msg' and r['m']['type'] == 'hello':
        h = r['m']; print(' ', t(r['rx_ms']), 'hello: non-open zones', [(z['zone_id'], z['status']) for z in h['zones'] if z['status'] != 'OPEN'], 'leases', h['leases'], 'vehicles', len(h['vehicles']))
hb = [r['rx_ms'] for r in rows if r['kind'] == 'msg' and r['m']['type'] == 'heartbeat']
anyrx = [r['rx_ms'] for r in rows if r['kind'] in ('msg', 'unparseable')]
for a, b in zip(anyrx, anyrx[1:]):
    if b - a > 1500: print('  silence on whole link %s for %.1fs' % (t(a), (b - a) / 1000))
d = [b - a for a, b in zip(hb, hb[1:])]
if d: print('  heartbeat gaps >3s:', [(t(a), round((b - a) / 1000, 1)) for a, b in zip(hb, hb[1:]) if b - a > 3000])
other = [r for r in rows if r['kind'] == 'msg' and r['m']['type'] not in ('telemetry', 'heartbeat', 'hello', 'zone_event')]
for r in other[:20]: print('  OTHER', t(r['rx_ms']), json.dumps(r['m'])[:250])
print('  truncated/unparseable lines: %d of %d (%.2f%%)' % (kinds['unparseable'], len(anyrx), 100 * kinds['unparseable'] / max(1, len(anyrx))))

# ---- telemetry by truck, in arrival order ----
tel = collections.defaultdict(list)
for r in rows:
    if r['kind'] == 'msg' and r['m']['type'] == 'telemetry': tel[r['m'].get('vehicle_id')].append((r['rx_ms'], r['m']))

# ---- zones ----
print('== ZONES ==')
events = [(r['rx_ms'], r['m']) for r in rows if r['kind'] == 'msg' and r['m']['type'] == 'zone_event']
closed_windows = []; open_since = {}
for rx, m in events:
    note = ''
    if m['status'] == 'CLOSING': note = 'notice %.0fs' % ((m['effective_at_ms'] - m['server_time_ms']) / 1000)
    if m['status'] == 'CLOSED': open_since[m['zone_id']] = rx
    if m['status'] == 'OPEN' and m['zone_id'] in open_since:
        a = open_since.pop(m['zone_id']); closed_windows.append((m['zone_id'], a, rx)); note = 'closed for %.0fs' % ((rx - a) / 1000)
    print(' ', t(rx), m['zone_id'], m['status'], m.get('reason'), note)
for z, a in open_since.items(): closed_windows.append((z, a, rows[-1]['rx_ms']))
for z, a, b in closed_windows:
    inside = []
    for v, l in sorted(tel.items()):
        n = [(rx, m) for rx, m in l if a <= rx <= b and m.get('zone_id') == z]
        if n: inside.append('%s(%d msgs, %s, pos %.0f..%.0f)' % (v, len(n), '/'.join(sorted(set(str(m['state']) for _, m in n))), min(pos(m) or 0 for _, m in n), max(pos(m) or 0 for _, m in n)))
    print('  while %s CLOSED %s..%s, reported inside: %s' % (z, t(a), t(b), inside or 'none'))

# ---- per truck ----
print('== TRUCKS ==')
fleet_drain = {}
for v, l in sorted(tel.items(), key=lambda kv: str(kv[0])):
    issues = []
    seqs = [m.get('seq') for _, m in l]
    # resets: big drop while device clock advances
    mx = None; mx_dev = None; resets = []
    seen = {}; ident = 0; reorder = 0; last = None
    for rx, m in l:
        s = m.get('seq'); dv = num(m.get('t_device_ms'))
        if isinstance(s, int) and mx is not None and s < mx - 20:
            resets.append('%s %d->%d' % (t(rx), mx, s)); mx = s; seen = {}
        if isinstance(s, int):
            key = json.dumps(m, sort_keys=True)
            if s in seen: ident += seen[s] == key
            seen[s] = key
            if last is not None and s < last: reorder += 1
            last = s; mx = s if mx is None else max(mx, s)
    if resets: issues.append('SEQ RESET ' + ', '.join(resets))
    gaps = [(a, b) for (a, _), (b, _) in zip(l, l[1:]) if b - a > 2000]
    if gaps: issues.append('SILENT ' + ', '.join('%s %.0fs' % (t(a), (b - a) / 1000) for a, b in gaps))
    sk = [num(m.get('t_device_ms')) - rx for rx, m in l if num(m.get('t_device_ms')) is not None]
    skew = st.median(sk) if sk else 0
    if abs(skew) > 1500: issues.append('CLOCK SKEW %+.1fs' % (skew / 1000))
    socs = [(rx, num(m.get('soc_pct'))) for rx, m in l if num(m.get('soc_pct')) is not None]
    if socs and max(s for _, s in socs) <= 1.0: issues.append('SOC LOOKS LIKE A FRACTION (%.3f)' % socs[-1][1])
    # drain while tramming, %/min
    tram = [(rx, num(m.get('soc_pct'))) for rx, m in l if m.get('state') == 'TRAMMING' and num(m.get('soc_pct')) is not None]
    drain = None
    if len(tram) > 50 and tram[-1][0] > tram[0][0]:
        scale = 100 if socs and max(s for _, s in socs) <= 1.0 else 1
        drops = sum(max(0, a[1] - b[1]) for a, b in zip(tram, tram[1:]) if 0 < b[0] - a[0] < 2000)
        mins = sum(b[0] - a[0] for a, b in zip(tram, tram[1:]) if 0 < b[0] - a[0] < 2000) / 60000
        drain = drops * scale / mins if mins else None
        fleet_drain[v] = drain
    # malformed fields
    bad = collections.Counter()
    for _, m in l:
        for f in ('offset_m', 'soc_pct', 'speed_mps', 'payload_kg', 't_device_ms'):
            if f not in m: bad['missing ' + f] += 1
            elif num(m[f]) is None: bad['%s=%s' % (f, type(m[f]).__name__)] += 1
        if m.get('state') not in ('TRAMMING', 'LOADING', 'DUMPING', 'CHARGING', 'HOLDING', 'IDLE', 'MANUAL', 'ESTOPPED', 'FAULT'): bad['state=%r' % m.get('state')] += 1
        if m.get('segment_id') not in start: bad['segment=%r' % m.get('segment_id')] += 1
        elif m.get('zone_id') != [s['zone_id'] for s in route if s['segment_id'] == m['segment_id']][0]: bad['zone/segment mismatch'] += 1
        o = num(m.get('offset_m'))
        if o is not None and m.get('segment_id') in length and not 0 <= o <= length[m['segment_id']] + 0.01: bad['offset outside segment'] += 1
        sp = num(m.get('speed_mps'))
        if sp is not None and (sp < 0 or sp > 4.5): bad['speed %.1f' % sp] += 1
        so = num(m.get('soc_pct'))
        if so is not None and not 0 <= so <= 100: bad['soc %.1f' % so] += 1
    if bad: issues.append('MALFORMED ' + str(dict(bad.most_common(6))))
    # frozen position: speed > 0.5 reported, moving state, position unchanged across >5s of in-order msgs
    ordered = sorted(((m['seq'], rx, m) for rx, m in l if isinstance(m.get('seq'), int)), key=lambda x: x[0])
    frozen = []; run_start = None
    for (s1, r1, m1), (s2, r2, m2) in zip(ordered, ordered[1:]):
        p1, p2 = pos(m1), pos(m2); sp = num(m2.get('speed_mps')) or 0
        if p1 is not None and p2 is not None and abs(p2 - p1) < 0.01 and sp > 0.5 and m2.get('state') in ('TRAMMING', 'MANUAL'):
            run_start = run_start or (r1, p1)
        else:
            if run_start and r1 - run_start[0] > 5000: frozen.append('%s for %.0fs at %.0fm' % (t(run_start[0]), (r1 - run_start[0]) / 1000, run_start[1]))
            run_start = None
    if run_start and ordered[-1][1] - run_start[0] > 5000: frozen.append('%s for %.0fs+ at %.0fm (to end)' % (t(run_start[0]), (ordered[-1][1] - run_start[0]) / 1000, run_start[1]))
    if frozen: issues.append('FROZEN POSITION ' + ', '.join(frozen))
    # state / fault / task / control changes (in seq order, per reset epoch roughly)
    changes = []; prev = None
    for s, rx, m in ordered:
        k = (m.get('state'), tuple(m.get('faults') or []), m.get('task'), (m.get('control') or {}).get('mode'))
        if prev and k != prev and (k[0] not in ('TRAMMING', 'LOADING', 'DUMPING', 'tramming', 'loading') or k[1] or k[2] or k[3] != 'AUTO' or prev[1]):
            changes.append('%s %s%s%s' % (t(rx), k[0], ' ' + ','.join(k[1]) if k[1] else '', ' task=' + k[2] if k[2] else ''))
        prev = k
    if changes: issues.append('EVENTS ' + '; '.join(changes[:8]))
    s0 = socs[0][1] if socs else None; s1 = socs[-1][1] if socs else None
    lastm = l[-1][1]
    print('%s n=%d dupIdent=%d reorder=%d skew=%+.1fs soc %s->%s drain=%s/min | last %s %s %.0fm' % (
        v, len(l), ident, reorder, skew / 1000, s0, s1, '%.2f' % drain if drain else '?', lastm.get('state'), lastm.get('zone_id'), pos(lastm) or -1))
    for i in issues: print('    -', i)
if fleet_drain:
    med = st.median(fleet_drain.values())
    print('fleet median drain %.2f%%/min; outliers:' % med, {v: round(d / med, 1) for v, d in fleet_drain.items() if d > 1.6 * med or d < 0.5 * med})
"""Cut the failure-case fixtures in research/fixtures/ out of full captures.

Usage:
  python3 research/trim.py RUN2.jsonl RUN3.jsonl PROBE.jsonl OUTDIR

The full captures are 9–25 MB each and are not committed. Each fixture keeps the capture's
record format (kind, rx_ms, m | raw) and starts with one {"kind": "fixture"} line saying what
it shows. Windows are in seconds from the start of the source capture. Auth lines are dropped,
hello.site.name is redacted, and the probe's own printouts ("note" records) are left out.
"""
import json, os, sys

run2, run3, probe, outdir = [[json.loads(l) for l in open(f)] for f in sys.argv[1:4]] + [sys.argv[4]]

def clean(r):
    r = json.loads(json.dumps(r))
    if r.get('kind') == 'msg' and r['m'].get('type') == 'hello' and 'site' in r['m']: r['m']['site'] = {'name': '<redacted>'}
    return r

def select(rows, a, b, keep):
    t0 = rows[0]['rx_ms']
    for r in rows:
        if a <= (r['rx_ms'] - t0) / 1000 <= b and r['kind'] != 'note' and not (r['kind'] == 'sent' and '"auth"' in r.get('raw', '')) and keep(r):
            yield clean(r)

def is_type(r, *types): return r['kind'] == 'msg' and r['m'].get('type') in types
def truck(r, *vs): return is_type(r, 'telemetry') and r['m'].get('vehicle_id') in vs
def about(r, v):  # commands we sent, and acks/lease events, for one truck
    if r['kind'] == 'sent': return '"%s"' % v in r['raw']
    return is_type(r, 'command_ack', 'lease_event', 'drive_rejected') and r['m'].get('vehicle_id') == v
def link(r): return r['kind'] in ('connected', 'closed_by_peer', 'error') or is_type(r, 'hello', 'zone_event', 'heartbeat')

def first_window(rows, v, state):
    t0 = rows[0]['rx_ms']
    xs = [(r['rx_ms'] - t0) / 1000 for r in rows if truck(r, v) and r['m'].get('state') == state]
    return (xs[0], xs[0] + 20) if xs else (0, 0)

ld = first_window(run3, 'HT-05', 'LOADING')
cases = [
    ('frozen-truck', 'run3', 'HT-10 freezes at about +160 s: every field stays identical while seq and t_device_ms keep '
     'advancing in step with real time; it reports TRAMMING at 2.0 m/s with an unchanged position. For contrast, '
     'HT-05 while LOADING: also identical bodies, but speed 0 in a stationary state.',
     [(run3, 140, 220, lambda r: truck(r, 'HT-10')), (run3, ld[0], ld[1], lambda r: truck(r, 'HT-05'))]),
    ('seq-reset', 'run3', 'HT-01 seq drops from 887 to 1 at about +178 s while t_device_ms carries on.',
     [(run3, 168, 188, lambda r: truck(r, 'HT-01'))]),
    ('silent-truck', 'run3', 'HT-03 sends nothing for 53 s from about +91 s while heartbeats show the link is up.',
     [(run3, 85, 150, lambda r: truck(r, 'HT-03') or is_type(r, 'heartbeat'))]),
    ('truncated-lines', 'run3', 'Every unparseable line in a 15-minute run (87 of 48,597): JSON cut off mid-object, newline-terminated.',
     [(run3, 0, 10 ** 6, lambda r: r['kind'] == 'unparseable')]),
    ('fractional-soc', 'run3', 'HT-12 reports soc_pct as a fraction (0.82 meaning 82%) for the whole run.',
     [(run3, 0, 10, lambda r: truck(r, 'HT-12'))]),
    ('accepted-then-ignored-resume', 'probe', 'HT-02: lease taken and left to expire, then RESUME is ACCEPTED (+233 s) '
     'but the truck stays HOLDING for 70 s; a second RESUME under a new command_id (+303 s) moves it within 1.3 s.',
     [(probe, 215, 306, lambda r: truck(r, 'HT-02') or about(r, 'HT-02'))]),
    ('reverse-exit-zone', 'probe', 'HT-05, empty and 145 m into DECLINE: EXIT_ZONE reverses it at 3.0 m/s up the decline '
     'and holds it 2 m inside BAY, 53 s later. Includes every truck reporting BAY or DECLINE in the window, i.e. what '
     'it was reversing toward.',
     [(probe, 160, 222, lambda r: about(r, 'HT-05') or (is_type(r, 'telemetry') and r['m'].get('zone_id') in ('BAY', 'DECLINE')))]),
    ('two-zones-closing', 'probe', 'hello with DRAW_12 and TIP both CLOSING at once, and the zone events that follow.',
     [(probe, 0, 210, lambda r: is_type(r, 'hello', 'zone_event'))]),
    ('weak-pack', 'run3', 'HT-06 drains about 5x faster than the fleet (43.8 % at the start) and stops with '
     'BATTERY_DEPLETED in the incline at about +508 s. Thinned to keep the file small: HT-06 at 1 Hz '
     '(seq divisible by 5) plus every HT-06 message in FAULT, and every other truck at 0.2 Hz '
     '(seq divisible by 25) as the fleet baseline.',
     [(run3, 0, 540, lambda r: truck(r, 'HT-06') and (r['m'].get('seq', 1) % 5 == 0 or r['m'].get('state') == 'FAULT')),
      (run3, 0, 540, lambda r: is_type(r, 'telemetry') and r['m'].get('vehicle_id') != 'HT-06' and r['m'].get('seq', 1) % 25 == 0)]),
    ('link-drop-in-notice', 'run2', 'DRAW_12 goes CLOSING; 1 s later the link drops for 45 s (logins accepted then closed); '
     'the hello on reconnect still shows DRAW_12 CLOSING with its effective time.',
     [(run2, 370, 420, link)]),
]

os.makedirs(outdir, exist_ok=True)
for name, source, what, parts in cases:
    # A fixture cut in several parts is written in arrival order, as a replay expects.
    lines = sorted((r for rows, a, b, keep in parts for r in select(rows, a, b, keep)), key=lambda r: r['rx_ms'])
    with open(os.path.join(outdir, name + '.jsonl'), 'w') as f:
        f.write(json.dumps({'kind': 'fixture', 'case': name, 'source': source, 'shows': what}) + '\n')
        for r in lines: f.write(json.dumps(r) + '\n')
    print('%-30s %5d records' % (name, len(lines)))
// Shared harness for the fake gateway tests: a fake on a ManualClock with one authenticated
// in-process client. Not a test file itself (no .test.ts suffix).
import { ManualClock } from '../src/clock.ts';
import type { CommandAck, GatewayMessage, Telemetry } from '../src/protocol.ts';
import { FakeGateway, type FakeConfig, type TestClient } from '../fake/gateway.ts';
import { DLH1 } from '../fake/dlh1.ts';

export const T0 = 1_790_000_000_000;

export interface Harness {
  clock: ManualClock;
  gw: FakeGateway;
  client: TestClient;
  advance(ms: number): void;
  command(vehicle: string, action: string, extra?: Record<string, unknown>, operator?: string): CommandAck;
  sendCommand(body: Record<string, unknown>): CommandAck | undefined;
  drive(vehicle: string, leaseId: string, seq: number, throttle: number, sentMs?: number): void;
  latest(vehicle: string): Telemetry;
  telemetry(vehicle: string): Telemetry[];
  messages<T extends GatewayMessage['type']>(type: T): Array<Extract<GatewayMessage, { type: T }>>;
  // Advance in ticks until pred holds on the vehicle's telemetry; returns the elapsed ms, or -1.
  until(vehicle: string, pred: (t: Telemetry) => boolean, maxMs: number): number;
}

export function harness(config: Partial<FakeConfig> = {}, email = '<redacted-email>'): Harness {
  const clock = new ManualClock(T0);
  const gw = new FakeGateway(clock, { seed: 7, site: DLH1, blasts: 'none', ...config });
  gw.start();
  const client = gw.connect();
  let n = 0;

  // Indexed as lines arrive: re-scanning every message on every poll is quadratic.
  const byType = new Map<string, GatewayMessage[]>();
  const byVehicle = new Map<string, Telemetry[]>();
  const acks = new Map<string, CommandAck>();
  client.onMessage((m) => {
    const list = byType.get(m.type) ?? [];
    list.push(m);
    byType.set(m.type, list);
    if (m.type === 'telemetry') {
      const v = byVehicle.get(m.vehicle_id) ?? [];
      v.push(m);
      byVehicle.set(m.vehicle_id, v);
    }
    if (m.type === 'command_ack') acks.set(m.command_id, m);
  });
  const messages = <T extends GatewayMessage['type']>(type: T) => (byType.get(type) ?? []) as Array<Extract<GatewayMessage, { type: T }>>;
  const lastAck = (id: string) => acks.get(id);
  const telemetry = (v: string) => byVehicle.get(v) ?? [];
  client.send({ type: 'auth', email });

  const h: Harness = {
    clock, gw, client,
    advance: (ms) => clock.advance(ms),
    command(vehicle, action, extra = {}, operator = 'op1') {
      const command_id = `t-${++n}`;
      client.send({ type: 'command', command_id, vehicle_id: vehicle, action, operator_id: operator, ...extra });
      const ack = lastAck(command_id);
      if (!ack) throw new Error(`no ack for ${command_id}`);
      return ack;
    },
    sendCommand(body) {
      client.send({ type: 'command', ...body });
      return typeof body.command_id === 'string' ? lastAck(body.command_id) : undefined;
    },
    drive(vehicle, leaseId, seq, throttle, sentMs) {
      client.send({ type: 'drive', vehicle_id: vehicle, lease_id: leaseId, seq, throttle, ...(sentMs === undefined ? {} : { sent_ms: sentMs }) });
    },
    latest(v) {
      const t = telemetry(v).at(-1);
      if (!t) throw new Error(`no telemetry for ${v}`);
      return t;
    },
    telemetry,
    messages,
    until(vehicle, pred, maxMs) {
      const start = clock.now();
      while (clock.now() - start <= maxMs) {
        const t = telemetry(vehicle).at(-1);
        if (t && pred(t)) return clock.now() - start;
        clock.advance(50);
      }
      return -1;
    },
  };
  return h;
}
// TESTING.md L0.C4: the fake is deterministic. The same seed and the same inputs give a
// byte-identical output stream; a 15-minute day takes well under a second on a ManualClock.
import { test } from 'node:test';
import assert from 'node:assert/strict';
import { createHash } from 'node:crypto';
import { ManualClock } from '../src/clock.ts';
import { FakeGateway } from '../fake/gateway.ts';
import { DLH1 } from '../fake/dlh1.ts';

const T0 = 1_790_000_000_000;
const DAY_MS = 15 * 60_000;

// A scripted day: random blasts, and a fixed set of inputs at fixed times covering every kind of
// command, a lease with driving, an e-stop and malformed lines. Returns every line one client saw.
function runDay(seed: number): { lines: string[]; cpuMs: number } {
  const clock = new ManualClock(T0);
  const gw = new FakeGateway(clock, { seed, site: DLH1, blasts: 'random' });
  gw.start();
  const c = gw.connect();
  c.send({ type: 'auth', email: '<redacted-email>' });
  const cmd = (id: string, vehicle: string, action: string, extra: object = {}) =>
    c.send({ type: 'command', command_id: id, vehicle_id: vehicle, action, operator_id: 'det', ...extra });

  const started = process.cpuUsage();
  clock.advance(5_000);
  cmd('d1', 'HT-01', 'HOLD');
  cmd('d2', 'HT-02', 'EXIT_ZONE');
  cmd('d3', 'HT-03', 'RETURN_TO_BAY');
  clock.advance(10_000);
  cmd('d4', 'HT-01', 'RESUME');
  cmd('d1', 'HT-01', 'HOLD'); // resend: original result
  cmd('d1', 'HT-01', 'RESUME'); // reuse: COMMAND_ID_REUSED
  c.send('{"type":"command", broken');
  cmd('d5', 'HT-04', 'TAKE_CONTROL');
  const ack = c.messages().filter((m) => m.type === 'command_ack' && m.command_id === 'd5').at(-1);
  const lease = ack && ack.type === 'command_ack' ? ack.lease_id ?? '' : '';
  for (let i = 1; i <= 30; i++) {
    c.send({ type: 'drive', vehicle_id: 'HT-04', lease_id: lease, seq: i, throttle: 0.4, sent_ms: clock.now() });
    clock.advance(100);
  }
  cmd('d6', 'HT-04', 'RELEASE_CONTROL', { lease_id: lease });
  cmd('d7', 'HT-05', 'ESTOP');
  clock.advance(20_000);
  cmd('d8', 'HT-05', 'CLEAR_ESTOP');
  cmd('d9', 'HT-05', 'RESUME');
  gw.injectFault('HT-06', 'HYD_PRESSURE_LOW');
  clock.advance(DAY_MS - clock.now() + T0);
  const used = process.cpuUsage(started);
  gw.stop();
  return { lines: c.lines, cpuMs: (used.user + used.system) / 1000 };
}

const digest = (lines: string[]) => createHash('sha256').update(lines.join('\n')).digest('hex');

test('L0.C4 the same seed and inputs give a byte-identical stream', () => {
  const a = runDay(42);
  const b = runDay(42);
  assert.ok(a.lines.length > 50_000, `${a.lines.length} lines in a 15-minute day`);
  assert.equal(a.lines.length, b.lines.length);
  assert.equal(digest(a.lines), digest(b.lines));
  const types = new Set(a.lines.map((l) => (JSON.parse(l) as { type: string }).type));
  for (const t of ['hello', 'telemetry', 'heartbeat', 'zone_event', 'command_ack', 'lease_event']) {
    assert.ok(types.has(t), `the stream includes ${t}`);
  }
});

test('L0.C4 a different seed gives a different day', () => {
  assert.notEqual(digest(runDay(42).lines), digest(runDay(43).lines));
});

// CPU time, not wall time: the claim is that the fake never waits on the real clock, and wall time
// also counts whatever else the machine is doing (the probe test runs in parallel).
test('a 15-minute day takes well under a second of CPU', () => {
  runDay(1); // warm up the JIT
  const { cpuMs } = runDay(2);
  console.log(`15-minute day: ${cpuMs.toFixed(0)} ms of CPU`);
  assert.ok(cpuMs < 1_000, `took ${cpuMs.toFixed(0)} ms of CPU`);
});
// TESTING.md L1.1 and L1.3: rules about what product code may contain, checked over src/.
import { test } from 'node:test';
import assert from 'node:assert/strict';
import { existsSync, readFileSync, readdirSync } from 'node:fs';
import { join, relative } from 'node:path';

const SRC = new URL('../src/', import.meta.url).pathname;
// The fake gateway (test infrastructure) is held to the same rules: it takes a Clock, and its model
// knows no site. Its default site config is the one place this site's literals belong.
const FAKE = new URL('../fake/', import.meta.url).pathname;
const FAKE_SITE_CONFIG = 'dlh1.ts';

function sourceFiles(dir: string): string[] {
  if (!existsSync(dir)) return [];
  return readdirSync(dir, { withFileTypes: true }).flatMap((e) =>
    e.name.startsWith('._') ? [] : e.isDirectory() ? sourceFiles(join(dir, e.name)) : e.name.endsWith('.ts') ? [join(dir, e.name)] : [],
  );
}

// L1.1: only the clock adapter may touch the wall clock or timers.
const WALL_CLOCK = [
  /\bDate\.now\s*\(/,
  /\bnew\s+Date\s*\(/,
  /\bperformance\.now\s*\(/,
  /\bprocess\.hrtime\b/,
  /(?<![.\w])(setTimeout|setInterval|setImmediate|clearTimeout|clearInterval)\s*\(/,
];

// L1.3: this site's names and numbers. The product takes them from hello and zone_event instead.
const SITE_LITERALS = [
  /\b(DECLINE|L4_NORTH|DRAW_12|L4_SOUTH|INCLINE|TIP)\b/,
  /['"`]BAY['"`]/,
  /\bSEG-/,
  /\bHT-\d/,
  /\b1600(\.0)?\b/,
  /\b120_?000\b/,
];

function violations(text: string, rules: RegExp[]): string[] {
  return text.split('\n').flatMap((line, i) => rules.filter((r) => r.test(line)).map((r) => `line ${i + 1}: ${line.trim()}  [${r}]`));
}

test('L1.1 the rule catches each kind of wall-clock access', () => {
  for (const planted of ['const t = Date.now();', 'new Date()', 'performance.now()', 'process.hrtime.bigint()', 'setTimeout(f, 10)', 'clearInterval(h)']) {
    assert.equal(violations(planted, WALL_CLOCK).length, 1, planted);
  }
  assert.deepEqual(violations('clock.setTimeout(f, 10); clock.now()', WALL_CLOCK), []);
});

test('L1.1 no product module outside the clock adapter reads the wall clock', () => {
  const found = sourceFiles(SRC)
    .filter((f) => relative(SRC, f) !== 'clock.ts')
    .flatMap((f) => violations(readFileSync(f, 'utf8'), WALL_CLOCK).map((v) => `${relative(SRC, f)} ${v}`));
  assert.deepEqual(found, []);
});

test('L1.3 the rule catches each kind of site literal', () => {
  for (const planted of ["zone === 'DECLINE'", "if (z === 'BAY')", "'SEG-BAY'", "vehicle: 'HT-04'", 'const loop = 1600;', 'const notice = 120_000;']) {
    assert.equal(violations(planted, SITE_LITERALS).length, 1, planted);
  }
  assert.deepEqual(violations("segment.kind === 'bay'; const n = 16000;", SITE_LITERALS), []);
});

test('L1.3 product code contains none of this site\'s literals', () => {
  const found = sourceFiles(SRC).flatMap((f) => violations(readFileSync(f, 'utf8'), SITE_LITERALS).map((v) => `${relative(SRC, f)} ${v}`));
  assert.deepEqual(found, []);
});

test('L1.1 the fake gateway never reads the wall clock', () => {
  const found = sourceFiles(FAKE).flatMap((f) => violations(readFileSync(f, 'utf8'), WALL_CLOCK).map((v) => `fake/${relative(FAKE, f)} ${v}`));
  assert.deepEqual(found, []);
});

test('L1.3 the fake gateway\'s model contains none of this site\'s literals (only its default config does)', () => {
  const found = sourceFiles(FAKE)
    .filter((f) => relative(FAKE, f) !== FAKE_SITE_CONFIG)
    .flatMap((f) => violations(readFileSync(f, 'utf8'), SITE_LITERALS).map((v) => `fake/${relative(FAKE, f)} ${v}`));
  assert.deepEqual(found, []);
});

// Slow (about 2.5 min of real time: it runs research/probe.py against the fake over TLS), so it runs
// in `npm run test:slow` and `npm run check`, not in `npm test`.
// TESTING.md L0.C2: research/probe.py, pointed at the fake over TLS, gets the same ack sequence and
// reasons as the live probe did for S1 and S3-S8. Also the TLS transport itself.
//
// The probe runs in real time (it sleeps and waits on the wall clock), so this test takes a couple
// of minutes. It is interrupted when S9 starts: S9 waits up to 240 s for a frozen truck, which the
// fake has no injector for until milestone 2, and S9 is outside L0.C2. SIGINT runs the probe's own
// cleanup. The probe's environment is built here from scratch, so it can only reach 127.0.0.1.
//
// The comparison reads the probe's raw output file, never its printout (AI_LOG.md entry 1), and
// pairs each ack with the latest send of its command_id before it in the file, never by counting.
import { test, type TestContext } from 'node:test';
import assert from 'node:assert/strict';
import { spawn, spawnSync } from 'node:child_process';
import { copyFileSync, existsSync, mkdtempSync, readFileSync, rmSync } from 'node:fs';
import { tmpdir } from 'node:os';
import { join } from 'node:path';
import { connect } from 'node:tls';
import { SystemClock } from '../src/clock.ts';
import type { CommandAck, GatewayMessage, Hello, LeaseEvent, Telemetry } from '../src/protocol.ts';
import { buildSite } from '../src/site.ts';
import { FakeGateway } from '../fake/gateway.ts';
import { DLH1 } from '../fake/dlh1.ts';
import { listenTls } from '../fake/tls.ts';

const ROOT = new URL('../', import.meta.url).pathname;
const has = (cmd: string, arg: string) => !spawnSync(cmd, [arg], { stdio: 'ignore' }).error;
const HAVE_OPENSSL = has('openssl', 'version');
const HAVE_PYTHON = has('python3', '--version');

// A throwaway key and certificate for 127.0.0.1, made at test time and deleted after.
function makeCert(t: TestContext): { dir: string; key: Buffer; cert: Buffer; certPath: string } {
  const dir = mkdtempSync(join(tmpdir(), 'fake-gw-'));
  t.after(() => rmSync(dir, { recursive: true, force: true }));
  const r = spawnSync('openssl', ['req', '-x509', '-newkey', 'rsa:2048', '-nodes', '-days', '1', '-subj', '/CN=127.0.0.1',
    '-addext', 'subjectAltName=IP:127.0.0.1', '-keyout', join(dir, 'key.pem'), '-out', join(dir, 'cert.pem')], { stdio: 'pipe' });
  assert.equal(r.status, 0, `openssl failed: ${r.stderr}`);
  return { dir, key: readFileSync(join(dir, 'key.pem')), cert: readFileSync(join(dir, 'cert.pem')), certPath: join(dir, 'cert.pem') };
}

test('TLS transport: auth, hello, a command and its ack as NDJSON; an over-long line closes the connection', { skip: !HAVE_OPENSSL }, async (t) => {
  const { key, cert } = makeCert(t);
  const gw = new FakeGateway(new SystemClock(), { seed: 3, site: DLH1, blasts: 'none' });
  gw.start();
  const server = await listenTls(gw, { key, cert });
  t.after(async () => { gw.stop(); await server.close(); });

  const sock = connect({ host: '127.0.0.1', port: server.port, ca: cert });
  const lines: string[] = [];
  let buf = '';
  sock.on('data', (d: Buffer) => {
    buf += d.toString('utf8');
    for (let i = buf.indexOf('\n'); i >= 0; i = buf.indexOf('\n')) { lines.push(buf.slice(0, i)); buf = buf.slice(i + 1); }
  });
  const closed = new Promise<void>((resolve) => sock.on('close', () => resolve()));
  const waitFor = async (pred: (m: GatewayMessage) => boolean) => {
    for (let i = 0; i < 100; i++) {
      const found = lines.map((l) => JSON.parse(l) as GatewayMessage).find(pred);
      if (found) return found;
      await new Promise((r) => setTimeout(r, 20));
    }
    throw new Error('timed out');
  };
  await new Promise<void>((resolve) => sock.once('secureConnect', () => resolve()));
  sock.write(JSON.stringify({ type: 'auth', email: '<redacted-email>' }) + '\n');
  const hello = await waitFor((m) => m.type === 'hello') as Hello;
  assert.equal(hello.site_id, DLH1.site_id);
  sock.write(JSON.stringify({ type: 'command', command_id: 'tls-1', vehicle_id: DLH1.vehicles[0], action: 'HOLD', operator_id: 'op' }) + '\n');
  const ack = await waitFor((m) => m.type === 'command_ack') as CommandAck;
  assert.equal(ack.command_id, 'tls-1');
  assert.equal(ack.status, 'ACCEPTED');
  await waitFor((m) => m.type === 'telemetry');
  sock.write('x'.repeat(70 * 1024) + '\n');
  await closed;
});

// ---- the probe ----

type Rec = { kind: string; rx_ms: number; name?: string; raw?: string; m?: GatewayMessage };

// What the live probe got (research/README.md "Verified", fixtures accepted-then-ignored-resume and
// reverse-exit-zone), and what the spec says where the live run lost the ack or left no record.
// Each entry: [action, 'ACCEPTED' or the rejection reason].
const EXPECTED: Record<string, Array<[string, string]>> = {
  // live: the first HOLD's ack was lost on the radio; the fake has no loss in milestone 1, so the
  // spec's ACCEPTED. Resend: original ACCEPTED (verified). Reuse: COMMAND_ID_REUSED (verified).
  S1: [['HOLD', 'ACCEPTED'], ['HOLD', 'ACCEPTED'], ['RESUME', 'COMMAND_ID_REUSED'], ['RESUME', 'ACCEPTED']],
  S3: [['EXIT_ZONE', 'ACCEPTED'], ['RESUME', 'ACCEPTED']], // live: probe-119b43-5 and -6, both ACCEPTED
  // live: TAKE_CONTROL ACCEPTED with lease details, HOLD LEASE_HELD (holder probe), RESUME ACCEPTED
  // (and then ignored for 70 s: an ACCEPTED-then-ignored fault, milestone 2)
  S4: [['TAKE_CONTROL', 'ACCEPTED'], ['HOLD', 'LEASE_HELD'], ['RESUME', 'ACCEPTED']],
  // S5-S8: no raw live record in the repository (the full probe log was not committed); these are
  // the spec's answers, which the README's account of the live run does not contradict.
  S5: [['TAKE_CONTROL', 'ACCEPTED'], ['RELEASE_CONTROL', 'NOT_LEASE_HOLDER'], ['RELEASE_CONTROL', 'ACCEPTED'], ['RESUME', 'ACCEPTED']],
  S6: [['ESTOP', 'ACCEPTED'], ['HOLD', 'ESTOP_ACTIVE'], ['CLEAR_ESTOP', 'ACCEPTED'], ['RESUME', 'ACCEPTED']],
  S7: [['HOLD', 'UNKNOWN_VEHICLE'], ['HOLD', 'MISSING_OPERATOR'], ['DANCE', 'UNSUPPORTED_ACTION'], ['HOLD', 'BAD_COMMAND_ID'], ['<unparseable>', 'BAD_JSON']],
  S8: [['HOLD', 'INTERLOCK_ACTIVE']],
};

interface Send { at: number; step: string; id: string; action: string; vehicle: string | null; rx: number; ack: CommandAck | null }

// Pair every command the probe sent with its ack, by position in the probe's file (it writes sends
// and acks under one lock, in the order it saw them). An ack belongs to the latest send of its
// command_id recorded before it. On localhost an ack can be recorded a moment before its own send
// record (the probe writes 'sent' just after the bytes leave), so when that latest send is already
// answered, the ack belongs to the next send of the id. No time window: sends of one id are 50 ms
// apart in S1, and an earlier version of this with a 50 ms window misattributed them.
// Milestone 1 loses no acks; once milestone 2 loses some, this pairing must be revisited.
function pairAcks(recs: Rec[]): Send[] {
  const sends: Send[] = [];
  let step = '';
  for (const [at, r] of recs.entries()) {
    if (r.kind === 'step') step = (r.name ?? '').split(' ')[0]!;
    if (r.kind !== 'sent' || r.raw === undefined) continue;
    let c: Record<string, unknown> | null = null;
    try { c = JSON.parse(r.raw) as Record<string, unknown>; } catch { c = null; }
    if (c && c.type !== 'command') continue; // drive messages
    sends.push({
      at,
      step,
      id: c ? (typeof c.command_id === 'string' ? c.command_id : '<missing>') : '<unparseable>',
      action: c ? String(c.action) : '<unparseable>',
      vehicle: c && typeof c.vehicle_id === 'string' ? c.vehicle_id : null,
      rx: r.rx_ms,
      ack: null,
    });
  }
  for (const [at, r] of recs.entries()) {
    if (r.kind !== 'msg' || r.m?.type !== 'command_ack') continue;
    const ack = r.m;
    const ofId = sends.filter((s) => s.id === ack.command_id);
    const before = ofId.filter((s) => s.at < at).at(-1);
    const target = before && !before.ack ? before : ofId.find((s) => s.at > at && !s.ack);
    if (target) target.ack = ack;
  }
  return sends;
}

const outcome = (a: CommandAck | null) => (a === null ? 'NO_ACK' : a.status === 'ACCEPTED' ? 'ACCEPTED' : String(a.reason));

test('L0.C2 research/probe.py gets the live ack sequence from the fake for S1 and S3-S8', { skip: !HAVE_OPENSSL || !HAVE_PYTHON ? 'needs python3 and openssl' : false, timeout: 600_000 }, async (t) => {
  const { dir, key, cert, certPath } = makeCert(t);
  const faulted = DLH1.vehicles.at(-1)!; // S8 needs a truck in FAULT
  const gw = new FakeGateway(new SystemClock(), { seed: 11, site: DLH1, blasts: 'none' });
  gw.injectFault(faulted, 'HYD_PRESSURE_LOW');
  gw.start();
  const server = await listenTls(gw, { key, cert });
  t.after(async () => { gw.stop(); await server.close(); });

  const out = join(dir, 'probe-out.jsonl');
  const env = {
    PATH: process.env.PATH ?? '/usr/bin:/bin',
    GATEWAY_HOST: '127.0.0.1',
    GATEWAY_PORT: String(server.port),
    GATEWAY_EMAIL: '<redacted-email>',
    SSL_CERT_FILE: certPath,
    PYTHONUNBUFFERED: '1',
  };
  const child = spawn('python3', [join(ROOT, 'research/probe.py'), out, '--live'], { cwd: ROOT, env, stdio: ['ignore', 'pipe', 'pipe'] });
  let printout = '';
  child.stdout.on('data', (d: Buffer) => { printout += d.toString(); });
  child.stderr.on('data', (d: Buffer) => { printout += d.toString(); });
  const exited = new Promise<number | null>((resolve) => child.on('exit', (code) => resolve(code)));

  // Interrupt at S9 (see the header). Polling the probe's own file: it flushes every record.
  const poll = setInterval(() => {
    if (existsSync(out) && readFileSync(out, 'utf8').includes('"name": "S9 ')) { clearInterval(poll); child.kill('SIGINT'); }
  }, 250);
  const code = await exited;
  clearInterval(poll);
  if (process.env.PROBE_OUT) copyFileSync(out, process.env.PROBE_OUT);
  assert.ok(existsSync(out), `the probe wrote nothing; it printed:\n${printout}`);

  const recs = readFileSync(out, 'utf8').trim().split('\n').map((l) => JSON.parse(l) as Rec);
  assert.ok(recs.some((r) => r.kind === 'step' && r.name?.startsWith('S9')), `the probe never reached S9 (exit ${code}); it printed:\n${printout}`);
  const sends = pairAcks(recs);

  for (const [step, expected] of Object.entries(EXPECTED)) {
    const got = sends.filter((s) => s.step === step).map((s): [string, string] => [s.action, outcome(s.ack)]);
    assert.deepEqual(got, expected, `${step}: got ${JSON.stringify(got)}`);
  }

  // Beyond the acks: what the live probe measured, checked in the same raw file.
  const tele = (v: string) => recs.filter((r) => r.kind === 'msg' && r.m?.type === 'telemetry' && r.m.vehicle_id === v)
    .map((r) => ({ rx: r.rx_ms, m: r.m as Telemetry }));
  const send = (step: string, action: string) => sends.find((s) => s.step === step && s.action === action)!;

  // S1: HOLD took effect 1-6 s after it was accepted (live: 3.2 s), on the gateway's clock (see S4),
  // plus up to 200 ms of telemetry sampling and the real clock's late timers.
  const hold = send('S1', 'HOLD');
  const held = tele(hold.vehicle!).find((x) => x.rx > hold.rx && x.m.state === 'HOLDING')!;
  const toHold = held.m.t_device_ms - hold.ack!.server_time_ms;
  assert.ok(toHold >= 1_000 && toHold <= 6_500, `S1 HOLD took effect ${toHold} ms after acceptance`);

  // S3: EXIT_ZONE at the autonomous speed for its load, stopping 2.0 m outside the zone (live: 3.0 m/s
  // empty, 2.0 m outside).
  const hello = recs.find((r) => r.m?.type === 'hello')!.m as Hello;
  const { site } = buildSite(hello);
  const exit = send('S3', 'EXIT_ZONE');
  const s3 = tele(exit.vehicle!).filter((x) => x.rx >= exit.rx - 1_000);
  const zone = site.zoneAt(site.toLoop(s3[0]!.m.segment_id, s3[0]!.m.offset_m)!)!;
  const moving = s3.filter((x) => x.m.task === 'EXIT_ZONE' && x.m.speed_mps > 0);
  assert.ok(moving.length > 0, 'S3 moved');
  const loaded = moving[0]!.m.payload_kg > 0;
  const heading = moving[0]!.m.direction;
  const expectedSpeed = loaded ? 2.0 : 3.0; // reverse and forward alike (reverse loaded is the spec-assumed value)
  assert.ok(moving.every((x) => x.m.speed_mps === expectedSpeed), `S3 speed ${expectedSpeed} (${heading}, loaded ${loaded})`);
  const stopped = s3.find((x) => x.rx > moving.at(-1)!.rx && x.m.state === 'HOLDING')!;
  const stopAt = site.toLoop(stopped.m.segment_id, stopped.m.offset_m)!;
  const r = zone.ranges[0]!;
  const outside = heading === 'REV' ? site.loopLengthM - ((stopAt - r.startM + site.loopLengthM) % site.loopLengthM) : (stopAt - (r.startM + r.lengthM) + site.loopLengthM) % site.loopLengthM;
  assert.ok(Math.abs(outside - 2.0) < 0.011, `S3 stopped ${outside} m outside ${zone.zoneId}`);
  assert.equal(stopped.m.task, null);

  // S4: deadman never before 500 ms after the grant, lease EXPIRED ~10 s after it (live 10.1 s),
  // truck HOLDING afterwards. Timed on the gateway's clock, not on the probe's receive times: under
  // load the probe has recorded GRANTED 140 ms late, making a 501 ms deadman look like 370 ms. In
  // milestone 1 t_device_ms is the gateway's clock exactly (no skew injector yet). The upper bounds
  // allow for the real clock's late timers and up to 200 ms of telemetry sampling.
  const take = send('S4', 'TAKE_CONTROL');
  const leaseEv = recs.filter((x) => x.m?.type === 'lease_event' && x.m.vehicle_id === take.vehicle).map((x) => ({ rx: x.rx_ms, m: x.m as LeaseEvent }));
  const granted = leaseEv.find((e) => e.m.event === 'GRANTED' && e.rx >= take.rx - 50)!;
  const expired = leaseEv.find((e) => e.m.event === 'EXPIRED' && e.rx > granted.rx)!;
  const deadman = tele(take.vehicle!).find((x) => x.rx > granted.rx && x.m.control.deadman)!;
