import json, sys, collections
# Which numeric fields arrive as floats (2.0) and which as ints, per message type, in a capture.
types = collections.defaultdict(lambda: collections.Counter())
def walk(t, prefix, x):
    if isinstance(x, bool) or x is None: return
    if isinstance(x, float): types[t][prefix + ':float'] += 1
    elif isinstance(x, int): types[t][prefix + ':int'] += 1
    elif isinstance(x, dict):
        for k, v in x.items(): walk(t, prefix + '.' + k, v)
    elif isinstance(x, list):
        for v in x: walk(t, prefix + '[]', v)
for f in sys.argv[1:]:
    for l in open(f):
        r = json.loads(l)
        if r.get('kind') == 'msg': walk(r['m'].get('type'), '', r['m'])
for t, c in types.items():
    print(t, dict(c))

