  assert.ok(after.length > 250);
  assert.equal(new Set(after.map(body)).size, 1, 'one body, repeated');
  for (let i = 1; i < after.length; i++) {
    assert.equal(after[i]!.seq, after[i - 1]!.seq + 1);
