// Controller runs: a large seq drop starts a new one. Device time of each seq, to place a lost
// seq in or out of an outage (the device clock is skewed, so offset it by the run's median lag).
let seen = new Set<number>(), max = -Infinity;
const runs: Array<{ seqs: Map<number, number> }> = [{ seqs: new Map() }];
for (const x of l) {
  if (max !== -Infinity && x.seq < max - RESET_DROP) { seen = new Set(); max = -Infinity; runs.push({ seqs: new Map() }); }
  if (seen.has(x.seq)) dup++;
  else if (x.seq < max) reord++;
  seen.add(x.seq);
  max = Math.max(max, x.seq);
  runs.at(-1)!.seqs.set(x.seq, x.rx);
}

input.new_string:
// Controller runs: a large seq drop starts a new one. A message that arrives late from the run
// before (its seq near that run's highest) still belongs to that run, not to a third one.
const runs: Array<{ seqs: Map<number, number>; max: number }> = [];
for (const x of l) {
  let run = runs.findLast((r) => x.seq >= r.max - RESET_DROP && x.seq <= r.max + RESET_DROP);
  if (!run) { run = { seqs: new Map(), max: -Infinity }; runs.push(run); }
  if (run.seqs.has(x.seq)) dup++;
  else if (x.seq < run.max) reord++;
  run.max = Math.max(run.max, x.seq);
  if (!run.seqs.has(x.seq)) run.seqs.set(x.seq, x.rx);
}

