  S1: [['HOLD', 'NO_ACK'], ['HOLD', 'ACCEPTED'], ['RESUME', 'COMMAND_ID_REUSED'], ['RESUME', 'ACCEPTED']],""")
rep("""// Milestone 1 loses no acks; once milestone 2 loses some, this pairing must be revisited.""","""// With milestone 2's ack latency (150 ms-2.6 s) the localhost race no longer arises, and a lost ack
// leaves its send unanswered: the probe waits for each ack before its next send of the same id.""")
rep("""  const gw = new FakeGateway(new SystemClock(), { seed: 11, site: DLH1, blasts: 'none' });""","""  // Acks as slow as live, and S1's first ack lost as it was live: the first command the probe sends.
