60	    }
61	  }
62	
63	  // An ack. Its server_time_ms stays the time the gateway got the command, as live; it arrives
64	  // later. `n` is the order the command was received in, for CommandMatch.
65	  ack(line: string, ack: CommandAck, n: number, action: string): void {
66	    const r = this.#rngAck, b = this.#b, f = this.#f;
67	    const invalid = ack.reason === 'BAD_JSON' || ack.reason === 'BAD_COMMAND_ID';
68	    // Commands that act at once (e-stop, leases) were acked within 0.7 s live; the rest up to 2.6 s.
69	    const immediate = ['ESTOP', 'CLEAR_ESTOP', 'TAKE_CONTROL', 'RELEASE_CONTROL'].includes(action);
70	    const max = immediate ? b.ackDelayImmediateMaxMs : b.ackDelayMaxMs;
71	    const delay = invalid
72	      ? Math.round(r.uniform(b.ackDelayInvalidMinMs, b.ackDelayInvalidMaxMs))
73	      : Math.round(Math.exp(r.uniform(Math.log(b.ackDelayMinMs), Math.log(max)))); // log-uniform
74	    const lost = r.chance(b.lostAckProbability);
75	    if (matches(f.lostAcks, lost, { n, command_id: ack.command_id, vehicle_id: ack.vehicle_id ?? '', action })) {
76	      this.#log.event(this.#clock.now(), ack.vehicle_id, 'lost_ack', { command_id: ack.command_id, action, status: ack.status });
77	      return;
78	    }
79	    this.#at(f.ackLatency ? delay : 0, line);
80	  }
